cat > /tmp/batchfix_check_test.go <<'EOF'
package shadow

import (
	"errors"
	"testing"
	"time"
)

func TestBatchReusedIDUnregisteredDeviceConflict(t *testing.T) {
	s, err := Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	at := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	if err := s.Register("dev-a", "1.0"); err != nil {
		t.Fatal(err)
	}
	rec, err := s.BatchUpdateDesired("req-1", "op", at, []BatchDevice{
		{DeviceID: "dev-a", Revision: 0, Config: []byte(`{"x":1}`)},
	})
	if err != nil {
		t.Fatal(err)
	}
	// 复用标识，设备换成未登记的 dev-b：应返回 ErrRequestConflict
	_, err = s.BatchUpdateDesired("req-1", "op", at, []BatchDevice{
		{DeviceID: "dev-b", Revision: 0, Config: []byte(`{"x":1}`)},
	})
	if !errors.Is(err, ErrRequestConflict) {
		t.Fatalf("want ErrRequestConflict, got %v", err)
	}
	// 混合已登记与未登记设备也一样
	_, err = s.BatchUpdateDesired("req-1", "op", at, []BatchDevice{
		{DeviceID: "dev-a", Revision: 1, Config: []byte(`{"x":1}`)},
		{DeviceID: "dev-b", Revision: 0, Config: []byte(`{"y":2}`)},
	})
	if !errors.Is(err, ErrRequestConflict) {
		t.Fatalf("mixed list: want ErrRequestConflict, got %v", err)
	}
	// 原记录仍可查询且不变
	got, err := s.GetBatchRequest("req-1")
	if err != nil || got.Revisions["dev-a"] != rec.Revisions["dev-a"] || got.Operator != "op" || !got.Time.Equal(at) {
		t.Fatalf("record changed: %+v %v", got, err)
	}
	// dev-a 状态未被冲突提交影响
	g, err := s.Get("dev-a")
	if err != nil || g.Revision != 1 {
		t.Fatalf("dev-a state changed: %+v %v", g, err)
	}
	// 相同内容重发仍返回首次结果
	rec2, err := s.BatchUpdateDesired("req-1", "op", at, []BatchDevice{
		{DeviceID: "dev-a", Revision: 0, Config: []byte(`{ "x": 1.0 }`)},
	})
	if err != nil || rec2.Revisions["dev-a"] != 1 {
		t.Fatalf("replay failed: %+v %v", rec2, err)
	}
	// 格式非法的复用仍按输入错误拒绝
	if _, err = s.BatchUpdateDesired("req-1", "op", at, []BatchDevice{
		{DeviceID: "dev-a", Revision: 0, Config: []byte(`{"x":1}`)},
		{DeviceID: "dev-a", Revision: 0, Config: []byte(`{"x":1}`)},
	}); !errors.Is(err, ErrDuplicateDevice) {
		t.Fatalf("dup device: want ErrDuplicateDevice, got %v", err)
	}
	if _, err = s.BatchUpdateDesired("req-1", "op", at, []BatchDevice{
		{DeviceID: "dev-b", Revision: 0, Config: []byte(`[1,2]`)},
	}); !errors.Is(err, ErrInvalidConfig) {
		t.Fatalf("bad config: want ErrInvalidConfig, got %v", err)
	}
	// 新标识引用未登记设备仍返回 ErrDeviceNotFound，且不占用标识
	if _, err = s.BatchUpdateDesired("req-2", "op", at, []BatchDevice{
		{DeviceID: "dev-b", Revision: 0, Config: []byte(`{"x":1}`)},
	}); !errors.Is(err, ErrDeviceNotFound) {
		t.Fatalf("new id unregistered: want ErrDeviceNotFound, got %v", err)
	}
	if _, err = s.GetBatchRequest("req-2"); !errors.Is(err, ErrRequestNotFound) {
		t.Fatalf("req-2 should not be recorded: %v", err)
	}
}
EOF
cp /tmp/batchfix_check_test.go shadow/batchfix_check_test.go && go test ./shadow/ -run TestBatchReusedIDUnregisteredDeviceConflict -v; rm shadow/batchfix_check_test.go
